// The e2e harness's ONE substitution: the CLI under test hardcodes the AI Gateway
// origin (no env override exists in 0.4.2 — neither lib/models.ts's
// GATEWAY_MODELS_URL nor @ai-sdk/gateway's default baseURL), so the driver
// imports this package FIRST and it wraps globalThis.fetch at module init,
// rewriting that origin to the harness's local mock (SCRIPTC_E2E_GATEWAY).
// Everything else — the CLI, the AI SDK, commander — runs unchanged; the
// wrap is plain JS that behaves identically under Node, so the two lanes
// stay comparable. Module-evaluation order guarantees the patch is live
// before any command code runs (the side-effect-order fixture pins that),
// and user-code fetch reads the live global (patched-global-fetch pins
// that).
const REAL = "https://ai-gateway.vercel.sh";
const base = process.env.SCRIPTC_E2E_GATEWAY;
if (base) {
  const orig = globalThis.fetch;
  globalThis.fetch = function fetch(input, init) {
    let url =
      typeof input === "string"
        ? input
        : input && typeof input.url === "string"
          ? input.url
          : String(input);
    if (url.startsWith(REAL)) url = base + url.slice(REAL.length);
    return orig(url, init);
  };
}
export {};
